288: export function createItemWorkbench(deps: ItemWorkbenchDeps = {}) {
289: 	const queryClient = deps.queryClient ?? useQueryClient();
290: 	const client = () => queryClient;
291: 	const requests = deps.requests ?? {};
292: 	const url = deps.url ?? (() => page.url);
293: 	const itemId = deps.itemId ?? (() => page.params.itemId);
294: 	const visit = deps.visit ?? ((href: string) => goto(href));
295: 	const notify = deps.notify ?? toast;
296: 	const successFlashMs = deps.successFlashMs ?? SUCCESS_FLASH_MS;
297: 
298: 	// ── List ──────────────────────────────────────────────────────────────
299: 
300: 	const table = createCursorTableUrl({
301: 		sort: { fields: { slug: "slug" }, default: "slug" },
302: 		filters: ["archived", "availability"],
303: 		defaultPageSize: 25,
304: 		...(deps.url && { url: deps.url }),
305: 		...(deps.navigate && { navigate: deps.navigate }),
306: 	});
307: 
308: 	const archived = $derived(
309: 		pickOption(ARCHIVE_FILTERS, table.filter("archived"), "exclude"),
310: 	);
311: 	const availability = $derived(
312: 		pickOption(AVAILABILITY_FILTERS, table.filter("availability"), "all"),
313: 	);
314: 	const listRequest = $derived.by(
315: 		(): NonNullable<InventoryItemsListData["query"]> => {
316: 			const { limit, cursor, q, direction } = table.request;
317: 			return {
318: 				limit,
319: 				direction,
320: 				archived,
321: 				...(availability !== "all" && { availability }),
322: 				...(q && { q }),
323: 				...(cursor && { cursor }),
324: 			};
325: 		},
326: 	);
327: 
328: 	const routeId = $derived(itemId());
329: 	const creating = $derived(routeId === "new");
330: 	const managedId = $derived(routeId && !creating ? routeId : undefined);
331: 
332: 	const list = createQuery(
333: 		() => ({
334: 			...inventoryItemsListOptions({ query: listRequest }),
335: 			...(requests.list && {
336: 				queryFn: () => requests.list!({ query: listRequest }),
337: 			}),
338: 			enabled: !routeId,
339: 			placeholderData: keepPreviousData,
340: 			select: (response: InventoryItemsListResponse) => response.data,
341: 		}),
342: 		client,
343: 	);
344: 
345: 	/** The list's own query string, carried to item routes and back. */
346: 	const listSearch = $derived.by(() => {
347: 		const params = new URLSearchParams(url().searchParams.toString());
348: 		params.delete("slug");
349: 		const query = params.toString();
350: 		return query ? `?${query}` : "";
351: 	});
352: 
353: 	const listHref = () => `${ITEMS_PATH}${listSearch}`;
354: 	const itemHref = (slug: string) => `${ITEMS_PATH}/${slug}${listSearch}`;
355: 
356: 	// ── Routed selection ─────────────────────────────────────────────────
357: 
358: 	function showQuery(slugOrId: string) {
359: 		return {
360: 			...inventoryItemsShowOptions({ path: { slugOrId } }),
361: 			...(requests.show && {
362: 				queryFn: () => requests.show!({ path: { slugOrId } }),
363: 			}),
364: 		};
365: 	}
366: 
367: 	const routedItem = createQuery(
368: 		() => ({
369: 			...showQuery(managedId ?? ""),
370: 			enabled: Boolean(managedId),
371: 			select: (response: InventoryItemsShowResponse) => response.data,
372: 		}),
373: 		client,
374: 	);
375: 
376: 	const selected = $derived(managedId ? routedItem.data : undefined);
377: 	// A primitive, so a refetch of the same item does not reset the drafts.
378: 	const selectedSlug = $derived(selected?.slug);
379: 
380: 	// Deep link for the loan queue's "Open item" maintenance links: `?slug=`
381: 	// resolves through the show endpoint (archive-agnostic) and lands on the
382: 	// item's route. Day-to-day code search goes through the list's `q`.
383: 	let lookedUpSlug: string | undefined;
384: 	$effect(() => {
385: 		const slug = url().searchParams.get("slug")?.trim();
386: 		if (!slug || slug === lookedUpSlug) return;
387: 		lookedUpSlug = slug;
388: 		void lookUpSlug(slug);
389: 	});
390: 
391: 	async function lookUpSlug(slug: string) {
392: 		try {
393: 			const response = await queryClient.fetchQuery(showQuery(slug));
394: 			await visit(`${ITEMS_PATH}/${response.data.slug}`);
395: 		} catch (cause) {
396: 			notify.error(apiErrorMessage(cause, "No item matches that code"));
397: 		}
398: 	}
399: 
400: 	// ── Reads the forms need ─────────────────────────────────────────────
401: 
402: 	const categories = createQuery(
403: 		() => ({
404: 			...inventoryCategoriesIndexOptions(),
405: 			...(requests.categories && { queryFn: requests.categories }),
406: 			select: (response: InventoryCategoriesIndexResponse) =>
407: 				response.data.categories,
408: 		}),
409: 		client,
410: 	);
411: 	const containers = createQuery(
412: 		() => ({
413: 			...inventoryContainersIndexOptions(),
414: 			...(requests.containers && { queryFn: requests.containers }),
415: 			select: (response: InventoryContainersIndexResponse) =>
416: 				response.data.containers,
417: 		}),
418: 		client,
419: 	);
420: 
421: 	function definitionsOf(categoryId: () => string | undefined) {
422: 		return createQuery(() => {
423: 			const path = { categoryId: categoryId() ?? "" };
424: 			return {
425: 				...inventoryStructureListDefinitionsOptions({ path }),
426: 				...(requests.definitions && {
427: 					queryFn: () => requests.definitions!({ path }),
428: 				}),
429: 				enabled: Boolean(categoryId()),
430: 				select: (response: InventoryStructureListDefinitionsResponse) =>
431: 					response.data.definitions,
432: 			};
433: 		}, client);
434: 	}
435: 
436: 	const maintenance = createQuery(() => {
437: 		const path = { slugOrId: selected?.slug ?? "" };
438: 		return {
439: 			...inventoryItemsListMaintenanceOptions({ path }),
440: 			...(requests.maintenance && {
441: 				queryFn: () => requests.maintenance!({ path }),
442: 			}),
443: 			enabled: Boolean(selected),
444: 			select: (response: InventoryItemsListMaintenanceResponse) =>
445: 				response.data.periods,
446: 		};
447: 	}, client);
448: 
449: 	const categoryOptions = $derived(
450: 		(categories.data ?? []).map((category) => ({
451: 			value: category.id,
452: 			label: category.name,
453: 		})),
454: 	);
455: 	const containerOptions = $derived(
456: 		(containers.data ?? [])
457: 			.filter((container) => !container.archivedAt)
458: 			.map((container) => ({ value: container.id, label: container.name })),
459: 	);
460: 
461: 	// ── Drafts ───────────────────────────────────────────────────────────
462: 
463: 	const create = $state<CreateFields>({
464: 		categoryId: "",
465: 		containerId: "",
466: 		notes: "",
467: 		values: {},
468: 	});
469: 
470: 	function resetCreate() {
471: 		create.categoryId = "";
472: 		create.containerId = "";
473: 		create.notes = "";
474: 		create.values = {};
475: 	}
476: 
477: 	// Reset whenever another item is selected; a command's success rebases
478: 	// them on the item Phoenix answered with (`rebasedDrafts`).
479: 	let drafts = $derived.by(() => {
480: 		if (!selectedSlug) return undefined;
481: 		return untrack(() => (selected ? itemDrafts(selected) : undefined));
482: 	});
483: 	// Writable deriveds: reading `selectedSlug` resets them to their initial
484: 	// value whenever another item is selected; the page may assign them.
485: 	let managementTab = $derived.by((): ManagementTab => {
486: 		void selectedSlug;
487: 		return "details";
488: 	});
489: 	let deleteConfirmOpen = $derived.by(() => {
490: 		void selectedSlug;
491: 		return false;
492: 	});
493: 
494: 	const createDefinitions = definitionsOf(() => create.categoryId);
495: 	const detailsDefinitions = definitionsOf(() => drafts?.item.categoryId);
496: 	const categoryDefinitions = definitionsOf(() => drafts?.fields.categoryId);
497: 
498: 	const dirty = $derived.by(() =>
499: 		drafts
500: 			? dirtyOf(drafts)
501: 			: { details: false, placement: false, category: false },
502: 	);
503: 
504: 	function setValue(
505: 		target: DraftTarget,
506: 		definition: Pick<InventoryPropertyDefinition, "id" | "valueType">,
507: 		input: string,
508: 	) {
509: 		if (target === "create") {
510: 			create.values = withDraftInput(create.values, definition, input);
511: 		} else if (drafts && target === "details") {
512: 			drafts.fields.values = withDraftInput(
513: 				drafts.fields.values,
514: 				definition,
515: 				input,
516: 			);
517: 		} else if (drafts) {
518: 			drafts.fields.categoryValues = withDraftInput(
519: 				drafts.fields.categoryValues,
520: 				definition,
521: 				input,
522: 			);
523: 		}
524: 	}
525: 
526: 	/** A new category's properties start empty. */
527: 	function chooseCreateCategory(categoryId: string) {
528: 		if (categoryId === create.categoryId) return;
529: 		create.categoryId = categoryId;
530: 		create.values = {};
531: 	}
532: 
533: 	/**
534: 	 * The change-category draft. Its values start empty for another
535: 	 * category, and return to the stored ones for the item's own.
536: 	 */
537: 	function chooseNewCategory(categoryId: string) {
538: 		if (!drafts || categoryId === drafts.fields.categoryId) return;
539: 		drafts.fields.categoryId = categoryId;
540: 		drafts.fields.categoryValues =
541: 			categoryId === drafts.item.categoryId ? draftFromItem(drafts.item) : {};
542: 	}
543: 
544: 	// ── Command outcomes ─────────────────────────────────────────────────
545: 
546: 	let flashing = $state<FlashedForm | null>(null);
547: 	let flashTimer: ReturnType<typeof setTimeout> | undefined;
548: 	$effect(() => () => clearTimeout(flashTimer));
549: 
550: 	function flash(form: FlashedForm, after?: () => void) {
551: 		flashing = form;
552: 		clearTimeout(flashTimer);
553: 		flashTimer = setTimeout(() => {
554: 			flashing = null;
555: 			after?.();
556: 		}, successFlashMs);
557: 	}
558: 
559: 	async function invalidateLists(slug: string) {
560: 		await Promise.all([
561: 			// Partial key: matches every filtered or paged Item list.
562: 			queryClient.invalidateQueries({ queryKey: inventoryItemsListQueryKey() }),
563: 			queryClient.invalidateQueries({
564: 				queryKey: inventoryItemsListMaintenanceQueryKey({
565: 					path: { slugOrId: slug },
566: 				}),
567: 			}),
568: 		]);
569: 	}
570: 
571: 	/**
572: 	 * Adopts the item Phoenix answered `own`'s command with: detail, drafts
573: 	 * (only `own`'s start again; see `rebasedDrafts`), then lists.
574: 	 */
575: 	async function adopt(item: InventoryOperatorItem, own: DraftGroup) {
576: 		if (managedId) {
577: 			queryClient.setQueryData<InventoryItemsShowResponse>(
578: 				inventoryItemsShowQueryKey({ path: { slugOrId: managedId } }),
579: 				{ data: item },
580: 			);
581: 		}
582: 		drafts = rebasedDrafts(drafts, item, own);
583: 		await invalidateLists(item.slug);
584: 	}
585: 
586: 	/**
587: 	 * An `enhance` callback: submits, then hands a result (never a
588: 	 * validation failure, which the form shows itself) to `outcome`.
589: 	 */
590: 	function submitted(
591: 		outcome: (result: ItemCommandResult) => void | Promise<void>,
592: 	) {
593: 		return async (form: ItemCommandSubmission) => {
594: 			if (!(await form.submit())) return;
595: 			const result = form.result;
596: 			if (result) await outcome(result);
597: 		};
598: 	}
599: 
600: 	/**
601: 	 * A management form's command. A refusal stays inline in the form; a
602: 	 * success adopts the item and flashes the form's button.
603: 	 */
604: 	function edited(form: Exclude<FlashedForm, "create">) {
605: 		return submitted(async (result) => {
606: 			if (!result.ok) return;
607: 			flash(form);
608: 			await adopt(result.data, form);
609: 		});
610: 	}
611: 
612: 	/** Archive and restore answer with a toast either way. */
613: 	function lifecycle(success: string) {
614: 		return submitted(async (result) => {
615: 			if (!result.ok) {
616: 				notify.error(result.error);
617: 				return;
618: 			}
619: 			notify.success(success);
620: 			await adopt(result.data, "archive");
621: 		});
622: 	}
623: 
624: 	const enhance = {
625: 		/**
626: 		 * Flashes the button, then opens the new item's route. No toast: it
627: 		 * would cover the next submit.
628: 		 */
629: 		create: submitted(async (result) => {
630: 			if (!result.ok) return;
631: 			const item = result.data;
632: 			const href = itemHref(item.slug);
633: 			queryClient.setQueryData<InventoryItemsShowResponse>(
634: 				inventoryItemsShowQueryKey({ path: { slugOrId: item.slug } }),
635: 				{ data: item },
636: 			);
637: 			flash("create", () => {
638: 				resetCreate();
639: 				void visit(href);
640: 			});
641: 			await invalidateLists(item.slug);
642: 		}),
643: 		update: edited("details"),
644: 		move: edited("placement"),
645: 		changeCategory: edited("category"),
646: 		startMaintenance: edited("maintenance"),
647: 		endMaintenance: edited("maintenance"),
648: 		archive: lifecycle("Item archived"),
649: 		restore: lifecycle("Item restored"),
650: 		/** Returns to the list: the navigation is the feedback, no toast. */
651: 		delete: submitted(async (result) => {
652: 			if (!result.ok) {
653: 				notify.error(result.error);
654: 				return;
655: 			}
656: 			deleteConfirmOpen = false;
657: 			if (managedId) {
658: 				queryClient.removeQueries({
659: 					queryKey: inventoryItemsShowQueryKey({
660: 						path: { slugOrId: managedId },
661: 					}),
662: 				});
663: 			}
664: 			await visit(listHref());
665: 			await queryClient.invalidateQueries({
666: 				queryKey: inventoryItemsListQueryKey(),
667: 			});
668: 		}),
669: 	};
670: 
671: 	return {
672: 		// List
673: 		list,
674: 		get items() {
675: 			return list.data?.items ?? [];
676: 		},
677: 		get totalCount() {
678: 			return list.data?.totalCount ?? 0;
679: 		},
680: 		/** The search box's draft; the URL follows after a debounce. */
681: 		get search() {
682: 			return table.search;
683: 		},
684: 		setSearch: (value: string) => table.setSearch(value),
685: 		/** Whether the list is narrowed by a search, for the empty state. */
686: 		get searching() {
687: 			return Boolean(table.request.q);
688: 		},
689: 		get archived() {
690: 			return archived;
691: 		},
692: 		/** Takes a select's value; one the page does not offer is ignored. */
693: 		setArchived(value: string) {
694: 			const next = pickOption(ARCHIVE_FILTERS, value, archived);
695: 			table.setFilter("archived", next === "exclude" ? null : next);
696: 		},
697: 		get availability() {
698: 			return availability;
699: 		},
700: 		/** Takes a select's value; one the page does not offer is ignored. */
701: 		setAvailability(value: string) {
702: 			const next = pickOption(AVAILABILITY_FILTERS, value, availability);
703: 			table.setFilter("availability", next === "all" ? null : next);
704: 		},
705: 		get activeFilterCount() {
706: 			return Number(availability !== "all") + Number(archived !== "exclude");
707: 		},
708: 		clearFilters() {
709: 			table.setFilters({ archived: null, availability: null });
710: 		},
711: 		get paged() {
712: 			return Boolean(table.request.cursor || list.data?.nextCursor);
713: 		},
714: 		get previousCursor() {
715: 			return list.data?.previousCursor ?? null;
716: 		},
717: 		get nextCursor() {
718: 			return list.data?.nextCursor ?? null;
719: 		},
720: 		previousPage() {
721: 			table.goTo(list.data?.previousCursor);
722: 		},
723: 		nextPage() {
724: 			table.goTo(list.data?.nextCursor);
725: 		},
726: 		/** The list, with its search and filters. */
727: 		get listHref() {
728: 			return listHref();
729: 		},
730: 		get newItemHref() {
731: 			return `${ITEMS_PATH}/new${listSearch}`;
732: 		},
733: 		itemHref,
734: 
735: 		// Routed selection
736: 		/** Whether the route is an item or the create form, not the list. */
737: 		get routed() {
738: 			return Boolean(routeId);
739: 		},
740: 		get creating() {
741: 			return creating;
742: 		},
743: 		routedItem,
744: 		/** The managed item, once loaded. */
745: 		get selected() {
746: 			return selected;
747: 		},
748: 
749: 		// Reads
750: 		categories,
751: 		containers,
752: 		maintenance,
753: 		createDefinitions,
754: 		detailsDefinitions,
755: 		categoryDefinitions,
756: 		get categoryOptions() {
757: 			return categoryOptions;
758: 		},
759: 		get containerOptions() {
760: 			return containerOptions;
761: 		},
762: 
763: 		// Drafts
764: 		/** The create form's draft; `categoryId` goes through `chooseCreateCategory`. */
765: 		create,
766: 		/** The managed item's drafts; `categoryId` goes through `chooseNewCategory`. */
767: 		get drafts() {
768: 			return drafts?.fields;
769: 		},
770: 		/** The property drafts as their hidden inputs carry them. */
771: 		get encoded() {
772: 			return {
773: 				create: encodePropertyDraft(create.values),
774: 				details: encodePropertyDraft(drafts?.fields.values ?? {}),
775: 				category: encodePropertyDraft(drafts?.fields.categoryValues ?? {}),
776: 			};
777: 		},
778: 		get dirty() {
779: 			return dirty;
780: 		},
781: 		get canCreate() {
782: 			return Boolean(
783: 				create.categoryId && create.containerId && !createDefinitions.isPending,
784: 			);
785: 		},
786: 		setValue,
787: 		chooseCreateCategory,
788: 		chooseNewCategory,
789: 		get managementTab() {
790: 			return managementTab;
791: 		},
792: 		set managementTab(tab: string) {
793: 			managementTab = pickOption(MANAGEMENT_TABS, tab, managementTab);
794: 		},
795: 		get deleteConfirmOpen() {
796: 			return deleteConfirmOpen;
797: 		},
798: 		set deleteConfirmOpen(open: boolean) {
799: 			deleteConfirmOpen = open;
800: 		},
801: 
802: 		// Commands
803: 		enhance,
804: 		/** Whether `form`'s submit button is showing its success state. */
805: 		succeeded(form: FlashedForm) {
806: 			return flashing === form;
807: 		},
808: 	};
