232: function dirtyOf({ item, fields }: ItemDrafts) {
233: 	const stored = draftFromItem(item);
234: 	return {
235: 		details:
236: 			fields.notes.trim() !== (item.notes ?? "") ||
237: 			!sameDraft(fields.values, stored),
238: 		placement: fields.containerId !== (item.containerId ?? ""),
239: 		category:
240: 			fields.categoryId !== item.categoryId ||
241: 			!sameDraft(fields.categoryValues, stored),
242: 	};
243: }
