245: /**
246:  * The drafts once a command answered with `item` (ALE-416 follow-up). The
247:  * submitting form (`own`) starts again from the answer. Another form keeps
248:  * what the operator typed but has not saved yet, so a slow command cannot wipe
249:  * an edit made while it ran: the maintenance and archive notes always, and an
250:  * item-backed draft while it is unsaved and the answer left the facts it edits
251:  * unchanged. Every other draft follows the answer.
252:  */
253: function rebasedDrafts(
254: 	current: ItemDrafts | undefined,
255: 	item: InventoryOperatorItem,
256: 	own: DraftGroup,
257: ): ItemDrafts {
258: 	const next = itemDrafts(item);
259: 	if (!current || current.item.id !== item.id) return next;
260: 	const before = current.item;
261: 	const sameValues = sameDraft(draftFromItem(before), draftFromItem(item));
262: 	const dirty = dirtyOf(current);
263: 	const keeps = (group: keyof typeof dirty, unchanged: boolean) =>
264: 		group !== own && dirty[group] && unchanged;
265: 	const { fields } = current;
266: 
267: 	if (
268: 		keeps("details", (before.notes ?? "") === (item.notes ?? "") && sameValues)
269: 	) {
270: 		next.fields.notes = fields.notes;
271: 		next.fields.values = fields.values;
272: 	}
273: 	if (keeps("placement", before.containerId === item.containerId)) {
274: 		next.fields.containerId = fields.containerId;
275: 	}
276: 	if (keeps("category", before.categoryId === item.categoryId && sameValues)) {
277: 		next.fields.categoryId = fields.categoryId;
278: 		next.fields.categoryValues = fields.categoryValues;
279: 	}
280: 	if (own !== "maintenance") {
281: 		next.fields.maintenanceReason = fields.maintenanceReason;
282: 		next.fields.maintenanceEndNote = fields.maintenanceEndNote;
283: 	}
284: 	if (own !== "archive") next.fields.archiveReason = fields.archiveReason;
285: 	return next;
286: }
