40: /** The least an occurrence read needs to be labelled. */
41: export type OccurrenceStatusInput = Pick<
42: 	TrainingAnnouncementOccurrence,
43: 	"subject" | "outcome" | "delivery"
44: >;
45: 
46: /** The least a chip or card needs to name an occurrence. */
47: export type OccurrenceTitleInput = Pick<
48: 	TrainingAnnouncementOccurrence,
49: 	"subject" | "kind" | "threadName"
50: >;
51: 
52: /** The least the calendar needs to key an event. */
53: export type OccurrenceKeyInput = Pick<
54: 	TrainingAnnouncementOccurrence,
55: 	"subject" | "announcementId" | "date" | "holidayDate" | "phase"
56: >;
57: 
58: /**
59:  * Stable tone token for CSS classes. One token per visual group — the wording
60:  * may carry a reason suffix while the colour stays grouped.
61:  */
62: export type OccurrenceTone =
63: 	| "scheduled"
64: 	| "override"
65: 	| "skipped"
66: 	| "posting"
67: 	| "posted"
68: 	| "uncertain"
69: 	| "blocked"
70: 	| "missed"
71: 	| "unknown"
72: 	| "holiday";
73: 
74: export type OccurrenceStatus = {
75: 	label: string;
76: 	tone: OccurrenceTone;
77: };
78: 
79: function deliveryStatus(
80: 	state: DeliveryState,
81: 	reason: DeliveryReason,
82: ): OccurrenceStatus {
83: 	switch (state) {
84: 		case "frozen":
85: 		case "posting_message":
86: 		case "message_posted":
87: 		case "creating_thread":
88: 			return { label: "posting…", tone: "posting" };
89: 		case "delivered":
90: 			return { label: "posted", tone: "posted" };
91: 		case "thread_failed":
92: 			return { label: "posted, no thread", tone: "posted" };
93: 		case "message_uncertain":
94: 			return { label: "uncertain — check Discord", tone: "uncertain" };
95: 		case "blocked":
96: 			return {
97: 				label: `blocked — ${deliveryReasonLabel(reason)}`,
98: 				tone: "blocked",
99: 			};
100: 		case "skipped":
101: 			return {
102: 				label: `skipped — ${deliveryReasonLabel(reason)}`,
103: 				tone: "skipped",
104: 			};
105: 		case "missed":
106: 			return {
107: 				label: `missed — ${deliveryReasonLabel(reason)}`,
108: 				tone: "missed",
109: 			};
110: 	}
111: }
112: 
113: /** Every raw delivery reason, in the committee's next-step words. */
114: export function deliveryReasonLabel(reason: DeliveryReason): string {
115: 	// Phoenix retains rows whose reason was never established; they read as
116: 	// unknown rather than leaking an empty suffix.
117: 	if (reason === null) return "unknown reason";
118: 	switch (reason) {
119: 		case "holiday":
120: 			return "bank holiday";
121: 		case "disabled":
122: 			return "paused announcement";
123: 		case "suppressed":
124: 			return "skipped dates";
125: 		case "unconfigured_channel":
126: 			return "channel not configured";
127: 		case "invalid_copy":
128: 			return "invalid message text";
129: 		case "late":
130: 			return "too late to post";
131: 		case "permission":
132: 			return "Discord refused";
133: 		case "unknown_channel":
134: 			return "unknown channel";
135: 		case "payload_rejected":
136: 			return "Discord rejected the message";
137: 		case "timeout":
138: 			return "Discord timed out";
139: 		case "server_error":
140: 			return "Discord error";
141: 		case "worker_lost":
142: 			return "posting process interrupted";
143: 		case "unknown":
144: 			return "unknown reason";
145: 	}
146: }
147: 
148: /** The grouped display status of one `window` item. */
149: export function occurrenceStatus(
150: 	item: OccurrenceStatusInput,
151: ): OccurrenceStatus {
152: 	if (item.delivery) {
153: 		return deliveryStatus(item.delivery.state, item.delivery.reason);
154: 	}
155: 	if (item.subject === "holiday") {
156: 		return { label: "holiday notice", tone: "holiday" };
157: 	}
158: 	switch (item.outcome) {
159: 		case "post":
160: 			return { label: "scheduled", tone: "scheduled" };
161: 		case "post_override":
162: 			return { label: "text changed", tone: "override" };
163: 		case "skipped_holiday":
164: 			return { label: "bank holiday", tone: "skipped" };
165: 		case "skipped_disabled":
166: 			return { label: "paused", tone: "skipped" };
167: 		case "skipped_suppressed":
168: 			return { label: "skipped", tone: "skipped" };
169: 		case "missed":
170: 			return { label: "missed", tone: "missed" };
171: 		case "unknown":
172: 			return { label: "unknown", tone: "unknown" };
173: 	}
174: }
175: 
176: /**
177:  * The resolved title of one `window` item: the thread name Phoenix computed,
178:  * never the announcement's template. When rendering failed and there is no
179:  * resolved name, the kind (or the holiday notice) stands in rather than an
180:  * empty chip.
181:  */
182: export function occurrenceTitle(item: OccurrenceTitleInput): string {
183: 	if (item.threadName) return item.threadName;
184: 	if (item.subject === "holiday") return "Holiday notice";
185: 	if (item.kind) return `${KIND_LABELS[item.kind]} post`;
186: 	return "Training post";
187: }
188: 
189: /**
190:  * The calendar event id for one `window` item, mirroring the backend's
191:  * durable identity: an occurrence belongs to its announcement and send date,
192:  * a holiday item to its bank-holiday date and phase.
193:  */
194: export function occurrenceKey(item: OccurrenceKeyInput): string {
195: 	if (item.subject === "holiday") {
196: 		return `holiday:${item.holidayDate}:${item.phase}`;
197: 	}
198: 	return `occurrence:${item.announcementId}:${item.date}`;
199: }
